'use strict';
(()=>{const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const form=document.querySelector('#activate-form'),message=document.querySelector('#activate-message');if(!/^[A-Za-z0-9_-]{40,100}$/.test(token)){message.textContent='Lien absent ou invalide. Demandez une nouvelle invitation à votre administrateur.';form.querySelector('button').disabled=true;return;}form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));if(values.password!==values.password_confirmation){message.textContent='Les mots de passe doivent correspondre.';return;}const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('/auth/activate',{method:'POST',credentials:'same-origin',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,...values})});if(!response.ok)throw Error(response.status===429?'Trop de tentatives. Réessayez plus tard.':'Lien expiré, déjà utilisé ou activation indisponible.');form.reset();form.hidden=true;document.querySelector('#activate-login').hidden=false;message.textContent='Accès activé. Utilisez votre identifiant et le mot de passe choisi pour vous connecter.';document.querySelector('#activate-login').before(message);}catch(error){message.textContent=error instanceof TypeError?'Connexion impossible. Vérifiez votre réseau puis réessayez.':error.message;button.disabled=false;}}})();
